import{_ as a,o as e,c as r,a3 as i}from"./chunks/framework.DMtjdCb-.js";const l="/help/assets/library-overview.ja.B0kMKC5-.png",f=JSON.parse('{"title":"はじめに","description":"","frontmatter":{},"headers":[],"relativePath":"ja/index.md","filePath":"ja/index.md"}'),o={name:"ja/index.md"};function n(h,t,d,s,c,m){return e(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="はじめに" tabindex="-1">はじめに <a class="header-anchor" href="#はじめに" aria-label="Permalink to &quot;はじめに&quot;">​</a></h1><p>AnimeMachine は、作品情報、購読、手持ちの動画、プレーヤーへの入口をまとめて扱います。まずは「作品を探す → 1 話ダウンロードする → 再生する」までを一度進め、その後に既存のコレクションや設定を追加します。</p><p><img src="'+l+'" alt="作品一覧：画像、購読、保存状況を確認" loading="lazy"></p><h2 id="実行する機器を選ぶ" tabindex="-1">実行する機器を選ぶ <a class="header-anchor" href="#実行する機器を選ぶ" aria-label="Permalink to &quot;実行する機器を選ぶ&quot;">​</a></h2><table tabindex="0"><thead><tr><th>使用する機器</th><th>最初に読むページ</th></tr></thead><tbody><tr><td>Windows PC</td><td><a href="./desktop.html#windows">PC に導入</a></td></tr><tr><td>NAS、Docker を導入済みの Linux サーバー</td><td><a href="./docker.html">Linux・Docker に導入</a></td></tr><tr><td>macOS・Linux PC</td><td><a href="./desktop.html#macos-linux">PC に導入</a></td></tr><tr><td>すでに AnimeMachine の画面を開いている</td><td><a href="./first-use.html">初回ログイン</a></td></tr></tbody></table><p>PC 版は AnimeMachine を起動し、必要に応じてダウンロード用サービスを接続します。NAS の標準構成は Ani-RSS、qBittorrent、Torrent Collector も起動し、自動で接続します。</p><h2 id="最初の再生まで" tabindex="-1">最初の再生まで <a class="header-anchor" href="#最初の再生まで" aria-label="Permalink to &quot;最初の再生まで&quot;">​</a></h2><ol><li>使用する機器に導入し、<a href="./first-use.html">ログインと画面の確認</a>を行います。</li><li><a href="./subscribe.html">作品を 1 本購読</a>し、字幕と配信版を選びます。</li><li>動画が利用可能になったら<a href="./playback.html">再生</a>します。</li><li>その後、<a href="./continue-watching.html">まとめて続きを再生</a>したり、<a href="./collections.html">既存のコレクションを接続</a>したりできます。</li></ol><p>画像は操作の一例です。配信されている話数や版は時期によって変わるため、実際の検索結果から選んでください。</p><h2 id="画面と見比べる" tabindex="-1">画面と見比べる <a class="header-anchor" href="#画面と見比べる" aria-label="Permalink to &quot;画面と見比べる&quot;">​</a></h2><p>各章は一つの作業に対応し、手順では画面のボタン名を使用しています。画像をクリックすると原寸で確認できます。ページ上部で中文・English・日本語を切り替えられます。</p><p>完了している作業は飛ばして構いません。問題がある場合は<a href="./troubleshooting.html">困ったときは</a>、または各章の末尾を参照してください。</p>',12)])])}const _=a(o,[["render",n]]);export{f as __pageData,_ as default};
